local quests = WordHunterWoW_QuestDataByFlavor.classic.enUS
quests[3982] = { title = "What Is Going On?", description = "I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.\n\n<Gor'shak whispers.>\n\nThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.\n\n<Gor'shak laughs.>\n\nShhh! Do you hear that? Guards coming! DEFEND YOURSELF!", objectives = "Defend Gor'shak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4001] = { title = "What Is Going On?", description = "So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.\n\nGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.\n\nThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!", objectives = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.\n\nYou recall Gor'shak mentioning that Kharan is being held in a cell nearby.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4002] = { title = "The Eastern Kingdoms", description = "You bring excellent information, $N.\n\nAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.\n\nThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!\n\nAre you prepared?", objectives = "Speak with Thrall if you are prepared to take on the mission he has planned.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4003] = { title = "The Royal Rescue", description = "This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.\n\nPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.\n\nDO NOT HARM HER!", objectives = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4004] = { title = "The Princess Saved?", description = "You have slain my husband, $r! My child will be born into this world without a father.\n\n<Princess Moira points directly at you.>\n\nI assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act.\n\n<You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.>\n\nLeave me be, $r. I am certain your warchief will be eager to hear the results of his meddling.", objectives = "Return to Thrall!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4005] = { title = "Aquementas", description = "Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.\n\nThe eastmost peninsula is the secret...\n\nFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.\n\nAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items.", objectives = "Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.\n\nUse the Book of Aquor to summon Aquementas.\n\nAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4021] = { title = "Counterattack!", description = "The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!\n\nFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.\n\nWe're counting on you, $N.", objectives = "Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4022] = { title = "A Taste of Flame", description = "The flight is aware of your work in the Searing Gorge.\n\nShow it to me, $r. The molt, imbecile.", objectives = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4023] = { title = "A Taste of Flame", description = "You seek out the Flight? Present to me proof of your worth, mortal.", objectives = "Show Cyrus Therepentous proof of your worth.\n\nYou have a feeling that Cyrus already knows that you are unworthy.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4024] = { title = "A Taste of Flame", description = "I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.\n\nBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.\n\nUse the molt on his remains to safely extract the inner flame.\n\nSucceed and be rewarded.", objectives = "Travel to Blackrock Depths and slay Bael'Gar.\n\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\n\nReturn the Encased Fiery Essence to Cyrus Therepentous.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4041] = { title = "The Videre Elixir", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4061] = { title = "The Rise of the Machines", description = "The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, $N.\n\nYour first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin.", objectives = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.\n\nYou recall Theodora mentioning the golems and elementals of that region as being a source for these shards.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4062] = { title = "The Rise of the Machines", description = "G.L.A.\n\nThose are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank.\n\nTake this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search.", objectives = "Take the Elemental Shard Sample to Lotwil Veriatus.\n\nYou recall Theodora saying that Lotwil was stationed in a camp to the east.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4063] = { title = "The Rise of the Machines", description = "This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him.\n\nHe was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice.\n\nIf this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.", objectives = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4081] = { title = "KILL ON SIGHT: Dark Iron Dwarves", description = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.\n\nAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.\n\nAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.", objectives = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4082] = { title = "KILL ON SIGHT: High Ranking Dark Iron Officials", description = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!\n\nCompletion of this mission will result in a tribute.", objectives = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4083] = { title = "The Spectral Chalice", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4084] = { title = "Silver Heart", description = "I do not know the one you speak of, $N.\n\nBut worry not; if your friend was on a journey to find me, I do know what it was he desired.\n\nIn the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...\n\nNone... except those with enough power to do so. I can teach you of this power, $N.\n\nFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return.", objectives = "Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4101] = { title = "Cleansing Felwood", description = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.", objectives = "Bring 15 Blood Amber to Arathandris Silversky in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4102] = { title = "Cleansing Felwood", description = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.", objectives = "Bring 15 Blood Amber to Maybess Riverbreeze in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
