quests[4120] = { title = "The Strength of Corruption", description = "Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, $N.\n\nIn a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well.\n\nGo, $N. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.", objectives = "Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4121] = { title = "Precarious Predicament", description = "Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?\n\nYou will be destroyed!", objectives = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4122] = { title = "Grark Lorkrub", description = "I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.\n\nHe now sits in the Burning Steppes, safely under their protection - or so he thinks.\n\nTake these shackles, $N. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours.", objectives = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4123] = { title = "The Heart of the Mountain", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", objectives = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4124] = { title = "The Missing Courier", description = "An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.\n\nIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters.", objectives = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4125] = { title = "The Missing Courier", description = "It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.\n\nI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know.", objectives = "Locate the courier's boat somewhere along the coast of Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4126] = { title = "Hurley Blackbreath", description = "The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager.  The villains!  They don't deserve such a fine brew!\n\n$N, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!\n\nPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!", objectives = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4127] = { title = "Boat Wreckage", description = "Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.\n\nYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water...", objectives = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4128] = { title = "Ragnar Thunderbrew", description = "Ho, $n.  I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale.  He's looking for stalwart adventurers, and willing to pay plenty.\n\nTalk to Ragnar if you're interested.  He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.", objectives = "Speak with Ragnar Thunderbrew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4129] = { title = "The Knife Revealed", description = "The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.\n\nTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife.", objectives = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4130] = { title = "Psychometric Reading", description = "I'm a little wobbly still, sorry.  Anyway, I received some useful visions.\n\nRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.\n\nI need to rest, sorry $N.  Tell Gin what I've seen.  He needs to know.", objectives = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4131] = { title = "The Woodpaw Gnolls", description = "Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.\n\nI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them.", objectives = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4132] = { title = "Operation: Death to Angerforge", description = "You have done an exemplary job, $N. It is now time to send you on your last mission.\n\nGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.\n\nThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.", objectives = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4133] = { title = "Vivian Lagrave", description = "Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.\n\nSpeak with Vivian.  She awaits you.", objectives = "Speak with Shadowmaster Vivian Lagrave in Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4134] = { title = "Lost Thunderbrew Recipe", description = "It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.\n\nDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.\n\nAnd to find him, you may have to entice him by threatening his precious ale.", objectives = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4135] = { title = "The Writhing Deep", description = "Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.\n\nThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".\n\nIt would seem that you have located where Raschal ultimately went.", objectives = "Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4136] = { title = "Ribbly Screwspigot", description = "My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another.\n\nWell, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head.  I can't tell you how happy this makes the Screwspigots!  Our little Ribbly's finally worth something!\n\nBut now he's hiding out, deep in Blackrock Depths.  Please, find him and bring him to me!\n\nOr, if he won't come, then that's ok... just bring me his head.", objectives = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4141] = { title = "Muigin and Larion", description = "See Larion over there? It's HIS fault we're here!\n\nI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.\n\nHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.\n\nFirst thing though, I'll need some samples to study. Do you think you could collect some?", objectives = "Collect 15 Bloodpetals and return to Muigin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4142] = { title = "A Visit to Gregan", description = "I'm not quite sure what to make of this, $N. The plants... they seem to have some minimal intelligence.\n\nI'm no expert, though. But, I do know someone that is!\n\nHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.\n\nI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.", objectives = "Take a Bloodpetal to Gregan Brewspewer in Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4143] = { title = "Haze of Evil", description = "To tell you the truth, $N, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...\n\nAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.\n\nYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai Haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, $N!", objectives = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4144] = { title = "Bloodpetal Sprouts", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4145] = { title = "Larion and Muigin", description = "See Muigin over there? It's HIS fault we're lost!\n\nI'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here!\n\nTo make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle.\n\nWhy don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.", objectives = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4146] = { title = "Zapper Fuel", description = "You're in luck, $n! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.\n\nI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.", objectives = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4147] = { title = "Marvon's Workshop", description = "I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!\n\nI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!\n\nWe'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.", objectives = "Travel to Marvon Rivetseeker's workshop in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4148] = { title = "Bloodpetal Zapper", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4161] = { title = "Recipe of the Kaldorei", description = "Long ago, the night elves were called the kaldorei, a name that means \"children of the stars.\" Learning of the past is an important step in your path as a $c, $N, so listen well to what I have to tell you.\n\nThe kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, $N.\n\nGo out and collect seven small spider legs -- no more than that, and return to me.", objectives = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4181] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n$N, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4182] = { title = "Dragonkin Menace", description = "Life in the Burning Steppes is rife with conflict.\n\nJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.\n\nEnough lamenting! We have a problem, $N. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.", objectives = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4183] = { title = "The True Masters", description = "We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.\n\nIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.\n\nTake this letter to Magistrate Solomon. He will know what must be done.\n\n<Helendis hands you a sealed letter.>", objectives = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4184] = { title = "The True Masters", description = "This is grim news, $N. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?\n\nYou must take this information to Highlord Bolvar Fordragon in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost.", objectives = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.\n\nBolvar resides in Stormwind Keep. ", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4185] = { title = "The True Masters", description = "Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.\n\nSpeak with Lady Prestor, $N. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.", objectives = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4186] = { title = "The True Masters", description = "I am going to empower you as an acting deputy of Stormwind, $N.\n\nReturn to Magistrate Solomon in Lakeshire and deliver this decree.", objectives = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4201] = { title = "The Love Potion", description = "Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It's maddening!\n\nYou must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro.  You can place the water in this vial.\n\nPlease, $N, help a poor soul in her quest for happiness!", objectives = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4221] = { title = "Corrupted Windblossom", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4222] = { title = "Corrupted Windblossom", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4223] = { title = "The True Masters", description = "<Magistrate Solomon sighs.>\n\nYou must return to the Burning Steppes, $N. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.", objectives = "Speak with Marshal Maxwell in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4224] = { title = "The True Masters", description = "What? You thought you were the first? How many soldiers must we lose before Stormwind acts?\n\nWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.\n\nWhat we need is that documentation. Speak with Ragged John, $N. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.", objectives = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.\n\nYou recall Marshal Maxwell telling you to search for him in a cave to the north.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4241] = { title = "Marshal Windsor", description = "So that good for nothing coward says that Windsor is alive, eh?\n\nSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.\n\n<Maxwell laughs.>\n\nI bet you are getting tired of hearing that, aren't you?", objectives = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\n\nYou recall Ragged John talking about Windsor being dragged off to a prison.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4242] = { title = "Abandoned Hope", description = "Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.\n\nHe is a blind buffoon. Proof stands two feet away from him and he does not see.\n\nAs for my data, it's lost. Gone. Unrecoverable.\n\nShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.\n\nLeave me, $N.", objectives = "Give Marshal Maxwell the bad news.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4243] = { title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her!\n\nCan you help me find her?", objectives = "Find A-Me 01 in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4244] = { title = "Chasing A-Me 01", description = "A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, \"Replace Mithril Casing And Turn Power Off Then On.\"\n\nTaking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge.\n\nOnly trying it will tell.", objectives = "Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4245] = { title = "Chasing A-Me 01", description = "Checking to see if your prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the \"Off\" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the \"On\" position.\n\nThis is your last chance... are you sure this is what you want to do?", objectives = "Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4261] = { title = "Ancient Spirit", description = "Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos...\n\nThe skull of Gul'dan ensured that none were spared here. All fell to the corruption.\n\nEven now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, $N, tell me you will lead an ancient spirit away from here, where I may finally rest.\n\nOnce I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east.", objectives = "Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4262] = { title = "Overmaster Pyron", description = "The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.\n\n<Jalinda picks up some ashes from the ground and releases them into the air.>\n\nOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!\n\nHe guards the entrance at the Blackrock Quarry.", objectives = "Slay Overmaster Pyron and return to Jalinda Sprig.\n\nYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4263] = { title = "Incendius!", description = "Are you sure Pyron said 'Incendius' when he died?\n\n<Jalinda swallows hard.>\n\nLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?\n\nDo you think you can handle another mission? I don't have anybody else to send, $N!\n\nWe will never get a team in if Incendius continues to raise Pyron from the ashes.\n\nYou'll have to find and destroy Lord Incendius!", objectives = "Find Lord Incendius in Blackrock Depths and destroy him!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4264] = { title = "A Crumpled Up Note", description = "The note has stains covering its surface. The text is barely legible, but you make out the following:\n\n...sweet irony...\n\n...the fall of the broken Alliance...\n\n...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...\n\n...Argelmach is almost done with the decryption of Windsor's notes.\n\nOur lord will rise from the depths and crush any that remain...\n\n-Emperor Dagran Thaurissan.", objectives = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4265] = { title = "Escaping the Hive", description = "The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.\n\n\"Thank Elune - you've saved me, friend! I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me. I could use a hand getting out of here; after that, would you let the Stronghold know that I am all right? I'll be fine - we just need to leave, and fast!\"", objectives = "Escort Raschal safely out of the Zukk'ash hive.\n\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4266] = { title = "A Hero's Welcome", description = "$N, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.\n\nGeneral Feathermoon is waiting for you in the main compound.", objectives = "Speak with Shandris Feathermoon in Feathermoon Stronghold.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4267] = { title = "Rise of the Silithid", description = "I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.\n\nYou're dismissed - good luck, $N; may Elune watch over us all.", objectives = "Bring Raschal's Report to Gracina Spiritmight in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4281] = { title = "Thalanaar Delivery", description = "This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished.\n\nExamining the parcel in detail reveals a hand written name of \"Falfindel Waywarder\" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient.", objectives = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4282] = { title = "A Shred of Hope", description = "<Marshal Windsor shakes the note excitedly.>\n\nDo you realize what this means, $N?\n\nPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.\n\nI hope you are ready to battle.\n\nVenture forth and find these two villains! Destroy them and return my lost information.", objectives = "Return Marshal Windsor's Lost Information.\n\nMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4283] = { title = "FIFTY! YEP!", description = "I'm going to let you in on a little secret, soldier. Come a little closer.\n\nI'M THE ONLY SANE ONE HERE!\n\nLook at these people! Would you believe that they're all insane!? Well they are! NUTS! CRAZY!\n\n<Oralius lowers his voice.>\n\nLet's just keep that between me, you, and my pal Captain Winky.\n\n<Oralius grabs at the air and squeezes.>\n\nAnyhooooo... I'm collecting badges to go along with my ogre ear collection. Orc is the flavor of the day. Fifty. GO!\n\n<Oralius blows into a horn.>\n\nSHIP IT!", objectives = "Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4284] = { title = "Crystals of Power", description = "I'm sure you've noticed 'em, $N. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?", objectives = "Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4285] = { title = "The Northern Pylon", description = "What could they be for? I can't get the thought out of my head!\n\nIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.\n\nAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, $N. I just know they exist.", objectives = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4286] = { title = "The Good Stuff", description = "Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky?\n\n<Oralius does his best impersonation of a pirate.>\n\nARRR MATEY! IT BE RIGHT!\n\nSee what I'm saying? You need to get in there and bring me back some samples of the good stuff.\n\nGet in there and shake your moneymaker!", objectives = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4287] = { title = "The Eastern Pylon", description = "During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, $N. I guess that they are quite large, with crystals lining their interiors.\n\nAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found\n\nSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?", objectives = "Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4288] = { title = "The Western Pylon", description = "My experiments so far have not yielded any positive results, $N. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.\n\nPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!\n\n$N, search the western area of the crater; a pylon is said to be somewhere in that area.", objectives = "Discover the location of the Western Crystal Pylon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4289] = { title = "The Apes of Un'Goro", description = "This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin.\n\nIf you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength.", objectives = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4290] = { title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nReturn to me afterwards.", objectives = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4291] = { title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, $N. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", objectives = "Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4292] = { title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", objectives = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4293] = { title = "A Sample of Slime...", description = "Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks.\n\nGather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.", objectives = "Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4294] = { title = "... and a Batch of Ooze", description = "Have you heard of the Un'Goro Crater, $N? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.\n\nIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.\n\nI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.", objectives = "Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4295] = { title = "Rocknot's Ale", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4296] = { title = "Tablet of the Seven", description = "I came to the Burning Steppes, following the legends of the Seven.  They were dwarves of great knowledge and power, and if you have knowledge and power, then wealth is sure to follow.\n\nThat's what I want.  Wealth!\n\nIf we can learn more of the Seven, then maybe we can get rich together.  The ruins of Thaurissan is rumored to keep the Tablet of the Seven, which holds knowledge of the ancient dwarves.  Find this tablet, copy its text and bring it to me.  Let's discover its secrets together!", objectives = "Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4297] = { title = "Food for Baby", description = "Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.\n\nI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched.", objectives = "Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4298] = { title = "Becoming a Parent", description = "Whoa, it was a lot more ready than I thought...", objectives = "Speak to Agnar Beastamer in the Hinterlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4300] = { title = "Bone-Bladed Weapons", description = "Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure.\n\nIn Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.", objectives = "Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4301] = { title = "The Mighty U'cha", description = "While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.\n\nI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter.", objectives = "Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4321] = { title = "Making Sense of It", description = "The information you have given me about the pylons is very interesting...\n\nGive me a moment to do some calculations, $N. Speak to me again in a moment and I should be able to give you the answer we have been looking for.", objectives = "Speak with J.D. Collie in a moment.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4322] = { title = "Jail Break!", description = "We need to get out of here, $N. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.", objectives = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4324] = { title = "Yuka Screwspigot", description = "Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands.\n\nSo, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.", objectives = "Speak with Yuka Screwspigot in the Burning Steppes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4341] = { title = "Kharan Mighthammer", description = "You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!\n\n<The King sobs.>\n\nAnd now she's gone, $N!\n\nI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!\n\nKharan is supposedly being held prisoner there... find him! I want answers!", objectives = "Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4342] = { title = "Kharan's Tale", description = "Please, hear me out before passing judgement!", objectives = "Listen as Kharan Mighthammer tells his story.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4343] = { title = "Corrupted Windblossom", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4361] = { title = "The Bearer of Bad News", description = "You must take this information back to King Magni, $N. He will know what to do!", objectives = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4362] = { title = "The Fate of the Kingdom", description = "It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.\n\nYou may be my last hope, $N. You must rescue my dear daughter, Moira!\n\nThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.\n\nAnd $N, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!", objectives = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4363] = { title = "The Princess's Surprise", description = "Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!\n\n<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>\n\nReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.\n\nWhether he approves or not, it shall be.", objectives = "Return to Ironforge and speak with King Magni Bronzebeard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4381] = { title = "Crystal Restore", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4382] = { title = "Crystal Force", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4383] = { title = "Crystal Ward", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4384] = { title = "Crystal Yield", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4385] = { title = "Crystal Charge", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4386] = { title = "Crystal Spire", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4401] = { title = "Corrupted Songflower", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4402] = { title = "Galgar's Cactus Apple Surprise", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, $N. If you bring me 10 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", objectives = "Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4403] = { title = "Corrupted Windblossom", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4421] = { title = "The Corruption of the Jadefire", description = "Not many seek adventure here... Felwood's corruption is widespread and indiscriminate.\n\nAs part of the Emerald Circle, I seek to heal this land, but there are some that wish it to fester.\n\nThe ones I speak of are the Jadefire satyrs that dwell to the northwest of here, at the Ruins of Constellas. Led by a particularly cruel satyr named Xavathras, they continue to spread the disease to any creatures they encounter.\n\nWe must defend this land that was once ours. Defeat Xavathras and destroy his minions.", objectives = "Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4441] = { title = "Felbound Ancients", description = "The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves.\n\nThe satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related.\n\nWe must try to purify the flute, $N. Bring me blessed water from the Temple of the Moon in Darnassus.", objectives = "Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4442] = { title = "Purified!", description = "Using the water of Elune, I will attempt to purify the flute. We must end this suffering...\n\nMay Elune guide my hands and heart.\n\nSpeak with me again in a moment.", objectives = "Speak to Eridan again in a moment.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[4443] = { title = "Corrupted Whipper Root", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
